import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { describe, it } from 'node:test'

import { CURRENT_ATTESTOR_VERSION, PROVIDER_CTX } from '#src/config/index.ts'
import httpProvider from '#src/providers/http/index.ts'
import { detectResponseCharset } from '#src/providers/http/response-charset.ts'
import type { ProviderParams, Transcript } from '#src/types/index.ts'
import { logger } from '#src/utils/index.ts'

// Generated by reclaim-tee/providers/TestHTMLCharsetReceiptContract.
// Keep this file byte-identical to that test's html_charset_receipts.json.
const fixtures: { name: string, contentType: string, charset: string, originalBody: string, response: string, match: string }[] = JSON.parse(
	readFileSync(new URL('./fixtures/html-charset-receipts.json', import.meta.url), 'utf8')
)

describe('Reclaim TEE charset receipt contract', () => {
	for(const fixture of fixtures) {
		it(fixture.name, async() => {
			assert.equal(detectResponseCharset(Buffer.from(fixture.originalBody, 'base64'), fixture.contentType), fixture.charset)
			const response = Buffer.from(fixture.response, 'base64')
			assert.equal(response.includes('PRIVATE'), false)
			const receipt: Transcript<Uint8Array> = [
				{ sender: 'client', message: Buffer.from('GET / HTTP/1.1\r\nHost: example.com\r\nConnection: close\r\n\r\n') },
				{ sender: 'server', message: response },
			]
			for(const type of ['contains', 'regex'] as const) {
				const params: ProviderParams<'http'> = {
					url: 'https://example.com/', method: 'GET',
					responseMatches: [{ type, value: fixture.match }],
				}
				await httpProvider.assertValidProviderReceipt({ receipt, params, logger, ctx: PROVIDER_CTX, clientVersion: CURRENT_ATTESTOR_VERSION })
				params.responseMatches = [{ type, value: 'NOT_IN_RECEIPT' }]
				await assert.rejects(async() => httpProvider.assertValidProviderReceipt({ receipt, params, logger, ctx: PROVIDER_CTX, clientVersion: CURRENT_ATTESTOR_VERSION }))
			}
		})
	}
})

describe('HTML charset selection', () => {
	const cases: [string, string, string | undefined][] = [
		['<meta charset=windows-1251>', 'text/html; charset=utf-8', 'utf-8'],
		['<meta charset=windows-1251>', 'text/html; charset=unknown', 'windows-1251'],
		['<meta charset=unknown><meta charset=windows-1251>', 'text/html', 'windows-1251'],
		['<meta charset=utf-16>', 'text/html', 'utf-8'],
		['<meta charset=x-user-defined>', 'text/html', 'windows-1252'],
		['<meta charset=windows-1251>', 'application/json', undefined],
		['<?xml-stylesheet encoding="windows-1251"?>', 'text/html', 'utf-8'],
		['<?xml version="1.0" note="encoding=windows-1251"?>', 'text/html', 'utf-8'],
		['<?xml encoding="windows-1251" encoding="utf-8"?>', 'text/html', 'utf-8'],
		['<?xml encoding="windows-1251"', 'text/html', 'utf-8'],
		['<?xml encoding="windows-1251"?>', 'text/html', 'windows-1251'],
		[' '.repeat(1100) + '<meta charset=windows-1251>', 'text/html', 'windows-1251'],
	]
	for(const [body, contentType, expected] of cases) {
		it(`${body.trim().slice(0, 75)} / ${contentType}`, () => {
			assert.equal(detectResponseCharset(Buffer.from(body), contentType), expected)
		})
	}
	it('prefers the BOM over the header', () => {
		assert.equal(detectResponseCharset(Buffer.from([0xef, 0xbb, 0xbf, 65]), 'text/html; charset=windows-1251'), 'utf-8')
	})
	it('rejects undeclared non-UTF-8 HTML', () => {
		assert.throws(() => detectResponseCharset(Buffer.from([0xff]), 'text/html'), /Cannot determine HTML response charset/)
	})
})
